async Task<int> LoadPriceAsync(string product)
{
    await Task.Delay(50);          // stands for a slow call
    return product.Length * 10;
}

int price = await LoadPriceAsync("pen");
Console.WriteLine(price);

async Task<int> LengthAsync(string text)
{
    await Task.Delay(50);
    return text.Length;
}

int[] lengths = await Task.WhenAll(LengthAsync("one"), LengthAsync("three"), LengthAsync("seven"));
Console.WriteLine(string.Join(", ", lengths));
Console.WriteLine(lengths.Sum());

async Task FailAsync()
{
    await Task.Delay(10);
    throw new InvalidOperationException("Service is down");
}

try
{
    await FailAsync();
}
catch (InvalidOperationException ex)
{
    Console.WriteLine($"Caught: {ex.Message}");
}

using var cts = new CancellationTokenSource();
cts.Cancel();

try
{
    await Task.Delay(5000, cts.Token);
    Console.WriteLine("Finished");
}
catch (OperationCanceledException)
{
    Console.WriteLine("Cancelled");
}

using var cts = new CancellationTokenSource();
int processed = 0;

try
{
    for (int i = 1; i <= 10; i++)
    {
        cts.Token.ThrowIfCancellationRequested();
        processed++;
        if (i == 3) cts.Cancel();
    }
}
catch (OperationCanceledException)
{
    Console.WriteLine($"Stopped after {processed} items");
}

async Task<string> SlowReportAsync(CancellationToken ct)
{
    await Task.Delay(2000, ct);
    return "report";
}

using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

try { Console.WriteLine(await SlowReportAsync(cts.Token)); }
catch (OperationCanceledException) { Console.WriteLine("Timed out"); }

